"use client";

import React, { useState, useEffect } from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';

const Header = () => {
    const [isOpen, setIsOpen] = useState(false);
    const [scrolled, setScrolled] = useState(false);
    const pathname = usePathname();

    useEffect(() => {
        const handleScroll = () => {
            if (window.scrollY > 20) {
                setScrolled(true);
            } else {
                setScrolled(false);
            }
        };

        window.addEventListener('scroll', handleScroll);
        return () => window.removeEventListener('scroll', handleScroll);
    }, []);

    const toggleMenu = () => {
        setIsOpen(!isOpen);
    };

    const navItems = [
        { name: 'Home', path: '/' },
        { name: 'About', path: '/about' },
        { name: 'Services', path: '/services' },
        { name: 'Blog', path: '/blog' },
        { name: 'Contact', path: '/contact' },
    ];

    return (
        <header style={{
            position: 'fixed',
            top: 0,
            left: 0,
            width: '100%',
            backgroundColor: scrolled ? 'rgba(10, 25, 47, 0.95)' : 'transparent',
            backdropFilter: scrolled ? 'blur(10px)' : 'none',
            WebkitBackdropFilter: scrolled ? 'blur(10px)' : 'none',
            boxShadow: scrolled ? '0 2px 10px rgba(0,0,0,0.3)' : 'none',
            zIndex: 1000,
            transition: 'all 0.3s ease',
            borderBottom: scrolled ? '1px solid rgba(255, 255, 255, 0.1)' : '1px solid transparent'
        }}>
            <div className="container" style={{
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
                padding: '0.5rem 20px',
                height: '80px'
            }}>
                <Link
                    href="/"
                    className="logo"
                    style={{
                        display: 'flex',
                        alignItems: 'center',
                        gap: '12px',
                        cursor: 'pointer',
                        textDecoration: 'none'
                    }}
                >
                    <img src="/logo.png" alt="Advocate RK &amp; Associates - Law Firm Logo Roorkee" style={{ height: '50px', objectFit: 'contain', filter: 'brightness(0) invert(1)' }} />
                    <div>
                        <span style={{ margin: 0, fontSize: '1.6rem', lineHeight: 1, color: 'white', letterSpacing: '-0.5px', fontWeight: 700, display: 'block' }}>Advocate RK</span>
                        <small style={{ fontSize: '0.75rem', color: 'var(--accent-color)', letterSpacing: '2px', textTransform: 'uppercase', display: 'block', marginTop: '4px' }}>&amp; Associates</small>
                    </div>
                </Link>

                <nav className={`nav ${isOpen ? 'open' : ''}`}>
                    <ul className={`nav-menu ${isOpen ? 'open' : ''}`}>
                        {navItems.map((item) => (
                            <li key={item.name}>
                                <Link
                                    href={item.path}
                                    onClick={() => setIsOpen(false)}
                                    className={`nav-link ${pathname === item.path ? 'active' : ''}`}
                                    style={{ textDecoration: 'none' }}
                                >
                                    {item.name}
                                </Link>
                            </li>
                        ))}
                        <li>
                            <Link href="/contact" className="btn" onClick={() => setIsOpen(false)} style={{
                                padding: '10px 24px',
                                fontSize: '0.9rem',
                                borderRadius: '50px',
                                color: '#0a192f',
                                textDecoration: 'none'
                            }}>
                                Consult Now
                            </Link>
                        </li>
                    </ul>
                </nav>

                <button
                    className="mobile-toggle"
                    onClick={toggleMenu}
                    aria-label="Toggle navigation"
                    style={{
                        fontSize: '1.8rem',
                        cursor: 'pointer',
                        color: 'white',
                        background: 'none',
                        border: 'none',
                        padding: '0.5rem',
                        alignItems: 'center',
                        justifyContent: 'center',
                        zIndex: 1100,
                        userSelect: 'none'
                    }}
                >
                    ☰
                </button>
            </div>
        </header>
    );
};

export default Header;
